#!/usr/bin/env python3
"""Resolve PR #132 against modern NestGo main without reverting runtime features."""
from pathlib import Path
import re

def patch(path, fn):
    p = Path(path)
    old = p.read_text()
    new = fn(old)
    if new == old:
        raise RuntimeError(f"integration patch had no effect: {path}")
    p.write_text(new)
    print("Integrated", path)

def change(src, old, new, where):
    if old not in src:
        raise RuntimeError(f"missing {where}: {old[:120]}")
    return src.replace(old, new, 1)

def compiler(s):
    # Main retains modern decorators, persistence providers, HTTP result types.
    name = re.search(r'var supported = map\[string\]bool\{([^\n]+)\}', s)
    if not name:
        raise RuntimeError("main supported map not found")
    extra = ["Expose", "Exclude", "ExcludeInput", "ExcludeOutput", "Transform",
             "TransformInput", "TransformOutput", "Type", "IsEmail", "IsCPF", "IsCNPJ",
             "IsCEP", "IsCNH", "IsPIS", "IsPlate", "IsPhone", "IsURL", "IsUUID",
             "IsNotEmpty", "IsOptional", "Matches", "Regex", "MinLength",
             "MaxLength", "Length", "Min", "Max", "Validate"]
    additions = ", ".join(f'"{key}": true' for key in extra if f'"{key}": true' not in name.group(0))
    if additions:
        s = s[:name.end()-1] + ", " + additions + s[name.end()-1:]
    s=change(s,
        '\trepositoryFiles := make(map[string][]byte)',
        '\tstructTypes, err := collectPackageTransformerStructs(dir, files)\n'
        '\tif err != nil { return err }\n'
        '\trepositoryFiles := make(map[string][]byte)', "collect transformer structs")
    target = '''\t\tif err := writeIfChanged(target, formatted); err != nil {
\t\t\treturn err
\t\t}
\t}
\tif err := writeIfChanged(filepath.Join(dir, "zz_modforge_metadata.go"), registry); err != nil {'''
    replacement = '''\t\tif err := writeIfChanged(target, formatted); err != nil {
\t\t\treturn err
\t\t}
\t\tcodecPath := strings.TrimSuffix(file.Path, ".mgo") + "_transformers_generated.go"
\t\tcodec, err := generatedPropertySource(file, structTypes)
\t\tif err != nil { return err }
\t\tif codec == nil {
\t\t\tif err := os.Remove(codecPath); err != nil && !os.IsNotExist(err) { return err }
\t\t} else if err := writeIfChanged(codecPath, codec); err != nil { return err }
\t}
\tif err := writeIfChanged(filepath.Join(dir, "zz_modforge_metadata.go"), registry); err != nil {'''
    s=change(s,target,replacement,"compiled codec emission")
    # A DTO-only source does not reference reflect; repositories and standard
    # NestGo metadata still use the main branch's reflect-based descriptors.
    old='out.WriteString("// Code generated by NestGo compiler. DO NOT EDIT.\\npackage " + pkg + "\\n\\nimport (\\n\\\"reflect\\\"\\n\\\"github.com/kevenmiano/nestgo/metadata\\\"\\n")'
    new='''out.WriteString("// Code generated by NestGo compiler. DO NOT EDIT.\\npackage " + pkg + "\\n\\nimport (\\n")
\tif len(controllers) > 0 || len(providers) > 0 || len(modules) > 0 || len(repositories) > 0 {
\t\tout.WriteString("\\"reflect\\"\\n")
\t}
\tout.WriteString("\\"github.com/kevenmiano/nestgo/metadata\\"\\n")'''
    s=change(s,old,new,"reflect import on DTO-only source")
    return s

def lexer(s):
    s=change(s,
             'func lexDecorators(path string, src []byte) (string, map[int][]Annotation, []marker, error) {',
             'func lexDecorators(path string, src []byte) (string, map[int][]Annotation, []marker, []marker, error) {',
             "lexer signature")
    s=change(s,'\tparams := []marker{}','\tparams := []marker{}\n\tproperties := []marker{}',"property markers")
    s=s.replace('return "", nil, nil, Diagnostic{', 'return "", nil, nil, nil, Diagnostic{')
    insert='''} else if name == "Expose" || name == "Exclude" || name == "ExcludeInput" ||
                name == "ExcludeOutput" || name == "Transform" || name == "TransformInput" ||
                name == "TransformOutput" || name == "Type" || isDTOValidator(name) {
                lineStart := lineBeginning(src, start)
                lineEnd := i
                for lineEnd < len(src) && src[lineEnd] != '\\n' { lineEnd++ }
                if strings.TrimSpace(string(src[lineStart:start])) != "" ||
                    strings.TrimSpace(string(src[i:lineEnd])) != "" {
                    return "", nil, nil, nil, Diagnostic{path, startLine, "property decorator must be on its own line"}
                }
                properties = append(properties, marker{start, name, argument})
            } else {'''
    s=change(s,
        '\t\t\t} else {\n\t\t\t\tlineStart := start',
        '\t\t\t'+insert+'\n\t\t\t\tlineStart := start',
        "property-decorator handling")
    s=change(s,'return string(out), annotations, params, nil',
        'return string(out), annotations, params, properties, nil',"lexer return")
    return s

def binding(s):
    s=change(s,'\t"reflect"','\t"reflect"\n\t"github.com/kevenmiano/nestgo/validation"',"validation import")
    s=change(s,'\treturn result, 0, nil','''\tif err := validation.Check(result); err != nil {
\t\treturn result, 400, err
\t}
\treturn result, 0, nil''',"validation after user-defined pipes")
    return s

def routes(s):
    # Merge strategy kept main's guard/pipe/HTTP responses; don't reintroduce
    # old reflection execution, only validate post-pipe Body DTOs.
    if '"github.com/kevenmiano/nestgo/validation"' not in s:
        s=change(s,'"github.com/kevenmiano/nestgo/metadata"','"github.com/kevenmiano/nestgo/metadata"\n\t"github.com/kevenmiano/nestgo/validation"',"runtime validation import")
    target='''\t\t\t\t\t\t\t\t\tv.Elem().Set(value)
\t\t\t\t\t\t\t\t}'''
    replacement='''\t\t\t\t\t\t\t\t\tv.Elem().Set(value)
\t\t\t\t\t\t\t\t\tif p.Kind == "Body" {
\t\t\t\t\t\t\t\t\t\tif err := validation.Check(v.Elem().Interface()); err != nil { return err }
\t\t\t\t\t\t\t\t\t}
\t\t\t\t\t\t\t\t}'''
    s=change(s,target,replacement,"reflective HTTP body validation")
    target='''\t\t\t\t\t\tif err != nil {
\t\t\t\t\t\t\tif status >= 400 && status <= 599 {'''
    replacement='''\t\t\t\t\t\tif err != nil {
\t\t\t\t\t\t\tvar validationErrors validation.Errors
\t\t\t\t\t\t\tif errors.As(err, &validationErrors) { return err }
\t\t\t\t\t\t\tif status >= 400 && status <= 599 {'''
    s=change(s,target,replacement,"keep typed validation errors")
    if '"errors"' not in s:
        s=change(s,'"encoding/json"','"encoding/json"\n\t"errors"',"errors import")
    if 'func respondValidationError(' not in s:
        s += '''
func respondValidationError(ctx httpadapter.Context, err error) error {
    var fields validation.Errors
    if !errors.As(err, &fields) { return respondError(ctx, 400, err.Error()) }
    ctx.Status(400)
    ctx.SetHeader("Content-Type", "application/json")
    payload := struct {
        StatusCode int `json:"statusCode"`
        Error string `json:"error"`
        Fields validation.Errors `json:"fields"`
    }{400, "Bad Request", fields}
    data, marshallErr := json.Marshal(payload)
    if marshallErr != nil { return respondError(ctx, 500, "Internal server error") }
    return ctx.Write(append(data,'\\n'))
}
'''
    return s

def request_pipeline(s):
    s=change(s,'\t"github.com/kevenmiano/nestgo/httpadapter"',
      '\t"github.com/kevenmiano/nestgo/httpadapter"\n\t"github.com/kevenmiano/nestgo/validation"',
      "validation import")
    target='''\tvar pipelineError *httpadapter.HTTPException'''
    replacement='''\tvar validationErrors validation.Errors
\tif errors.As(err, &validationErrors) {
\t\treturn respondValidationError(exec.Request, err)
\t}
\tvar pipelineError *httpadapter.HTTPException'''
    return change(s,target,replacement,"exception integration")

def go_mod(s):
    s=change(s,'require (\n\tgithub.com/spf13/cobra',
        'require (\n\tgithub.com/go-viper/mapstructure/v2 v2.5.0\n\tgithub.com/paemuri/brdoc/v4 v4.7.0\n\tgithub.com/spf13/cobra',
        "new dependencies")
    return s

def sidebar(s):
    return change(s,
      "'fundamentals/providers', 'fundamentals/compiler']",
      "'fundamentals/providers', 'fundamentals/compiler', 'fundamentals/dto-transformers']",
      "DTO docs nav")

for path,fn in [
    ("compiler/compiler.go",compiler),
    ("compiler/lexer.go",lexer),
    ("httpadapter/binding.go",binding),
    ("runtime/http_routes.go",routes),
    ("runtime/request_pipeline.go",request_pipeline),
    ("go.mod",go_mod),
    ("website/sidebars.js",sidebar),
]:
    patch(path,fn)
